// Writes docs/BEFORE-AFTER.md from the adversarial corpus, so the samples always match the engine.
const fs = require('fs'); const path = require('path');
const { strip } = require('../src/engine.js');
const corpus = require('../test/adversarial-corpus.js');
const fence = (t) => '```\n' + t.replace(/```/g, '`​``') + '\n```';
let md = '# Before and after\n\n' +
  'Generated by `node scripts/before-after.js` from `test/adversarial-corpus.js`. Every company, person, project and number is made up. ' +
  'Each sample is stripped on its own with default settings (hide-only, nothing cut).\n\n' +
  '**Review findings** are things StackStrip flags but leaves visible, such as numbers the AI may need. You choose whether to hide them.\n\n';
for (const s of corpus) {
  const r = strip(s.input, s.format ? { format: s.format } : {});
  const rev = (r.report.review || []).map((f) => '`' + f.text.replace(/`/g, "'") + '`' + (f.count > 1 ? ' ×' + f.count : '')).join(', ');
  md += '## ' + s.title + '\n\n' +
    '**State:** ' + (r.report.state === 'review' ? '⚠ Review required' : '✓ Known patterns hidden') + (rev ? ' · **Review:** ' + rev : '') + '\n\n' +
    '**Before**\n\n' + fence(s.input) + '\n\n**After**\n\n' + fence(r.text) + '\n\n';
}
fs.writeFileSync(path.join(__dirname, '..', 'docs', 'BEFORE-AFTER.md'), md);
console.log('docs/BEFORE-AFTER.md:', corpus.length, 'samples');
